insert into public.fi_dialogos (situacao,ordem,quem,en,pt) values ($q$t8$q$,9,$q$voce$q$,$q$Thank you! It was great talking to you.$q$,$q$Obrigado! Foi ótimo conversar com você.$q$) on conflict (situacao,ordem) do update set quem=excluded.quem,en=excluded.en,pt=excluded.pt;
insert into public.fi_historias (id,tipo,nivel,titulo,texto,glossario,pontos,ordem) values ($q$s1$q$,$q$travel$q$,$q$A2$q$,$q$The Missed Flight$q$,$q$Marco arrived at the airport at six o'clock. His flight to Lisbon was at seven. He went to the check-in desk, but the line was very long.
