insert into public.fi_historias (id,tipo,nivel,titulo,texto,glossario,pontos,ordem) values ($q$s5$q$,$q$travel$q$,$q$B1$q$,$q$Lost in Lisbon$q$,$q$Tom was walking in Lisbon when his phone battery died. He had no map, and all the streets looked the same. He needed to find the tram stop to go back to his hotel.
